"use strict";$(document).ready(function(){$("#takenAction").validate({errorClass:"invalid_field",validClass:"valid_field",ignore:".ignore",errorPlacement:function(error,element){"ActionId"!=element.attr("name")?error.insertAfter(element):error.appendTo(".actionId-errors")},submitHandler:function(form){var action=$(form).attr("action");return $.ajax({url:action,type:"POST",data:$(form).serialize(),cache:!1,processData:!1,success:function(data){if(console.log(data),data.success){data.result.data;$("#takenAction").trigger("reset"),$notification.success("",window.localization.processed_successfully,2e3,"fa fa-check"),setTimeout(function(){return window.location.reload()},1500)}else{var errors=data.errors;if(errors.length>0){var txt=MakeErrorsMsg(errors);$notification.error("",txt,3500,"fa fa-exclamation-circle")}}}}),!1}})});